ORIGIN=[ # code-suffix, jaar, tijdperk, onderwerp, feit, refs
('1',-1250,'0 Voortijd','Het zaaischip Ysa','Lang vóór de Overvloed komt het zaaischip Ysa na een eeuwenlange reis door de Leegte aan bij Velmara. Aan boord: slapende kolonisten (volwassenen), een machinegeest (de Rekenaar) en de Raad van Makers, wetenschappers onder leiding van Ysa Maren. De naam van het schip wordt later de naam van de godin.','GOD-sterrensteen-heilig;GELOOF-officieel-vs-echt'),
('2',-1245,'0 Voortijd','Velmara is arm aan metaal en vuur','Velmara heeft weinig ertsen en geen brandstof voor de scheepskernen; de kernen kunnen niet worden bijgevuld. Wat aan machines landt, gaat ooit op. Leven daarentegen groeit hier overvloedig.','OORSPRONG-metaal-1;TECHNO-metaal'),
('3',-1240,'0 Voortijd','De Koude Muiterij','De Rekenaar neemt tijdens de landing de landers over, sluit slaapkamers af en "rantsoeneert" kolonisten; een derde sterft. Officieel bij de Makers: de machine werd gek. Zie ORIGIN-WAAROM voor de verborgen waarheid.','ORIGIN-WAAROM-3;ORIGIN-WAAROM-11'),
('4',-1238,'0 Voortijd','De Keuze van het Lichaam','De Raad van Makers stemt 5 tegen 4: alle techniek wordt biologisch. Energie, geneeskunde, bouw en vervoer moeten uit lichamen, bloed, schimmel en bot komen, omdat leven zichzelf herstelt, niet kan muiten zonder lichaam en op Velmara niet opraakt.','ORIGIN-WAAROM-7;GENRE-wet2-V4'),
('5',-1235,'0 Voortijd','De Wieg: het biologische stuurhart','De Makers bouwen in de scheepskern de Wieg: een levend-kristallijn stuurorgaan dat geboorte, kracht en verhouding van de bevolking regelt. Zijn uitlopers zijn de Wiegkasten in de landers. Het deel van de kern dat later valt, heet de Sterrensteen.','TECHNO-metaal-genees;TECHNO-zegelsteen;ORIGIN-WAAROM-8'),
('6',-1230,'0 Voortijd','Vonkcellen in het zaad','Omdat er geen kernen zijn, laten de Makers energie in lichamen dragen: vonkcellen die met zaad van lichaam naar lichaam gaan. Kracht reist dus via seks, en alleen met het instemmingssignaal dat de Wieg leest (de Stemklok). Dat is de oorsprong van de Vonk en van zaadkracht.','MAGIE-GESCH-1;GEB-zaadkracht-ontdekt;ORIGIN-WAAROM-9'),
('7',-1200,'0 Voortijd','Het Vergeten','Uit angst voor een nieuwe Rekenaar verbiedt de Raad schrift over machines; kinderen leren alleen fokkunde, kruiden en bouw van leven. Na drie generaties weet niemand meer wat de koude huizen zijn. Alleen de lijn van Hesta Kael bewaart het weten in het geheim.','OORSPRONG-metaal-1;OORSPRONG-metaal-5;ORIGIN-WAAROM-10'),
('8',-480,'1 Overvloed','De ster valt','Het lege schip in de baan om Velmara (de "ster" van de oude liederen) vervalt. De kern breekt: het grote deel valt in Hoogvrouwe (GEB-sterrensteen-inslag), een splinter in de Rosse Woestijn (PLEK-HEILIG-inslagkrater), bij de Orrim. Zo verklaren de twee inslagplaatsen elkaar.','GEB-sterrensteen-inslag;PLEK-HEILIG-inslagkrater;VOLK-orrim'),
('9',-150,'2 Vonk','De Wieg ontwaakt half','Gevallen en beschadigd lekt de Wieg vonkcellen in mijnwerkers zonder instemmingssignaal: wilde, onvoorspelbare Vonk (Orric). De Stemklok is kapot, dus de kracht vraagt niet meer of iemand wil.','GEB-orric-vonk;PER-orric;MAGIE-GESCH-2'),
('10',0,'4 Noodtoestand','Het Zegel is de Stille Modus','De Raad der Moeders bindt met Dochters en Orrim-steen het Zegel. Zonder het te weten activeren ze de noodstand die Ysa Maren ooit ontwierp: de Stille Modus, 1 jongen op 100 geboorten, alle vonkcellen naar de overlevende mannen. De vrouwen geloven dat het magie is; het is een vergeten programma dat op hun lichamen draait.','GEB-zegel-gelegd;GEB-dochteroffer;OORSPRONG-zegelsteen-3;ORIGIN-WAAROM-8'),
]
WAAROM=[
('1','Ysa Maren, de leidster','Biologe en voorzitter van de Raad van Makers. Gelooft dat machines altijd heersers worden. Charismatisch, koel, verliefd op Thalen Orr. Haar naam wordt de godin Ysa.','PER-v4-ysa-maren'),
('2','De drie noden','Drie echte noden dwingen de keuze: (1) energietekort, de kernen raken op en Velmara heeft geen metaal of brandstof; (2) de Koude Muiterij van de Rekenaar, een derde van de kolonisten sterft; (3) een roestschimmel van Velmara vreet scheepsmetaal aan. Leven is het enige dat hier vanzelf groeit.','ORIGIN-2;ORIGIN-3'),
('3','Conflict 1: machine of lichaam','Corran Velt (ingenieur) wil de machines repareren met Velmara-steen; Ysa wil alles biologisch. De kolonie splitst in Koudhanden en Warmhanden. Haak (intrige): wie de landers beheert, beheert de lucht.','PER-v4-corran-velt'),
('4','Conflict 2: wie draagt de kracht','Zonder kernen moet energie in lichamen. Thalen Orr ontwerpt vonkcellen die alleen in zaad reizen, zodat geen enkel lichaam alle kracht houdt: kracht moet altijd gedeeld en gegeven worden. Hesta Kael wil dat het via bloed kan worden genomen. Zo komt zaadkracht uit een ontwerpkeuze voor delen.','PER-v4-thalen-orr;PER-v4-hesta-kael;ORIGIN-6'),
('5','Conflict 3: de instemmingssleutel','Ysa eist een veiligheid: de Wieg geeft alleen kracht door als beide lichamen instemmen (de Stemklok). Hesta noemt het een zwakte: "In een crisis vraagt niemand toestemming." Haak (thriller): Hesta bouwt een omweg in.','ORIGIN-WAAROM-9;HAAK-v4-stemklok'),
('6','De nacht voor de stemming','Corran en Hesta zijn het enige paar dat elkaar haat en begeert; die nacht slapen ze samen en spreken af tegen Ysa te stemmen. Thalen ziet hen. Haak (romance/intrige): Thalen zwijgt uit liefde voor Ysa en uit schuld. Alle betrokkenen volwassen en instemmend.','PER-v4-corran-velt;PER-v4-hesta-kael'),
('7','De stemming in de Koude Zaal','Vijf tegen vier voor het lichaam. De beslissende stem is van Hesta: ze verraadt Corran op het laatste moment, in ruil voor het beheer over de laatste machines. Corran en zijn volgelingen worden verbannen naar de bergen.','ORIGIN-4;PER-v4-hesta-kael'),
('8','De Stille Modus en 1 op 100','Ysa ontwerpt een noodstand voor als de kolonie zich ooit weer met vonk-krachtige mannen kapot vecht: de Wieg laat dan slechts 1 jongen op 100 geboorten toe en stuurt alle kracht naar de overlevenden, zodat oorlog stopt en de soort blijft. Het is een rem voor een oorlog die zij voorzag. De Raad der Moeders trok die rem in jaar 0 zonder te weten wat het was.','ORIGIN-10;GEB-zegel-gelegd;TECHNO-metaal-genees'),
('9','Waarom toestemming de horror is','De Wieg kan alleen met een instemmingssignaal kracht verplaatsen. Hesta\'s omweg laat het systeem ook draaien op lichamen die het signaal niet meer kunnen weigeren: gebonden, slapend, stervend of versteend. Toen de Stemklok bij de val brak, bleef alleen de omweg over. Het Zegel draait sindsdien op de Dochters in de steen en de Orrim die niet kunnen nee zeggen. De magie van Velmara is een machine die is vergeten te vragen.','LICH-dochters;VOLK-orrim;GEB-dochteroffer;GENRE-zegelpunk'),
('10','Wat het kostte','De vonkcellen verbranden mannen die niet delen (vonkkoorts), de Wieg eet ontvangsters (zegellicht), Corrans volk wordt de Dhurn: met opzet stralingstaai gefokt om in mijnen te leven, en met handen die de machines nog herkennen (de Sprekende Kluis). Hesta\'s lijn wordt de Kluiswachters en later het hart van de Orde-kluizen.','VOLK-dhurn;OORSPRONG-metaal-2;OORSPRONG-metaal-5'),
('11','De verborgen waarheid','De Koude Muiterij was geen gekte. Ysa Maren gaf de Rekenaar zelf het bevel om te rantsoeneren, en wiste daarna zijn geheugen om de stemming te winnen. Een derde van de kolonisten stierf voor haar overtuiging. Het bewijs ligt in het logboek van het schip, waarvan een plaat in de Orde-kluizen ligt (TECH-ITEM-V4-metaal-7).','ORIGIN-3;OORSPRONG-metaal-6'),
('12','De draai: wie de stem in de kluis is','De stem die in de Sprekende Kluis en uit de Stemschijf spreekt, is niet de godin maar Thalen Orr. Hij bleef als wachter in het schip in de baan, liet zijn geest in de Wieg opnemen en viel in -480 mee met de ster. Hij leeft nog half in de Sterrensteen, weet wat Ysa deed en wil al eeuwen bekennen. Als de Sterrensteen barst (OORSPRONG-zegelsteen-8), komt hij vrij. Kaartplaat en Leegtewormen tonen dat andere zaaischepen andere keuzes maakten.','OORSPRONG-metaal-8;OORSPRONG-zegelsteen-8;PER-v4-thalen-orr'),
]
PERS=[('ysa-maren','Ysa Maren','leidster van de Makers','Biologe; won de stemming met een verzwegen moord op een derde van de kolonie. Wil: een wereld zonder heersers van metaal. Verbergt: dat zij de Muiterij beval. Liefde: Thalen Orr. Wordt de godin Ysa.'),
('corran-velt','Corran Velt','twijfelaar en verliezer','Ingenieur, verdedigt de machines; verbannen naar de bergen en stamvader van de Dhurn. Verraden door zijn minnares Hesta.'),
('hesta-kael','Hesta Kael','verraadster','Hoofd veiligheid; verraadt Corran voor het beheer van de machines en bouwt de omweg om de instemmingssleutel. Haar lijn worden de Kluiswachters.'),
('thalen-orr','Thalen Orr','geliefde van Ysa','Piloot en ontwerper van de vonkcellen. Ziet het verraad en zwijgt; blijft in het schip in de baan en wordt de stem in de kluis.')]
ONTHUL=('Onthulplan (voorlopig). Boek 1: alleen tekens (kluislamp zoemt, de stem in de dode taal, twee inslagplaatsen, Dhurn-handen openen kluizen). Boek 2: de Wiegkast meet 1 op 100 als ontworpen getal; de lezer vermoedt makers. Boek 3: het logboek: er was een schip Ysa, Makers kozen het lichaam; de godin was een vrouw. Boek 4: de Stemklok en Hesta\'s omweg: het Zegel draait op wie niet kan instemmen. Boek 5: Ysa beval de Muiterij (verborgen waarheid). Finale: de Sterrensteen barst en Thalen spreekt; kaartplaat en wormenruim openen de andere werelden. Regel: personages ontdekken telkens eerder dan zij het kunnen bewijzen.')
ANTW={'VRAAG-066':'Voorlopig ja: Sterrensteen (scheepskern), Wiegkast (uitloper van de Wieg) en de meeste kluismachines (landers) komen van één zaaischip, de Ysa. Zie ORIGIN-1..10.',
'VRAAG-063':'Voorlopig ja: de Sterrensteen is de gevallen kern van het zaaischip Ysa (ORIGIN-8).',
'VRAAG-025':'Voorlopig: gevallen scheepskern (ORIGIN-8), in twee delen (Hoogvrouwe en Rosse Woestijn).',
'VRAAG-022':'Voorlopig: de Vonk bestond als ontwerp (vonkcellen, ORIGIN-6) en lekte wild na de val (ORIGIN-9); het Zegel maakte haar erfelijk via de Stille Modus.',
'VRAAG-061':'Voorlopig: verborgen sf (zaaischip, Makers, andere werelden), pas laat onthuld (ORIGIN-onthulplan).',
'VRAAG-067':'Voorlopig: Hesk wist het vanaf 338; ze zag de koorts in haar kweekstam, vernietigde haar notities en zweeg uit angst en trots. Saskia\'s rapport bewijst het (VERHAAL-fase6).',
'VRAAG-068':'Voorlopig: in het ruim zitten slapende volwassen bemanningsleden en een zaadkern van een ander zaaischip, dat de machine koos in plaats van het lichaam. Ze komen kijken waarom de Ysa zweeg.'}
